import { ComputerModel, ComputerVariant, ComputerSpecs } from "./types";

const RESOLUTION_MAP: { match: RegExp; label: string }[] = [
  { match: /4\.5k/i, label: "4.5K (4480×2520)" },
  { match: /3\.2k/i, label: "3.2K (3200×2000)" },
  { match: /3k/i, label: "3K (2880×1800)" },
  { match: /2\.8k/i, label: "2.8K (2880×1800)" },
  { match: /wqxga/i, label: "WQXGA (2560×1600)" },
  { match: /qhd\+/i, label: "QHD+ (2560×1600)" },
  { match: /wuxga/i, label: "WUXGA (1920×1200)" },
  { match: /fhd\+/i, label: "FHD+ (1920×1200)" },
  { match: /fhd/i, label: "FHD (1920×1080)" },
  { match: /qhd/i, label: "QHD (2560×1440)" },
];

function deriveResolution(display: string): string | undefined {
  if (display.includes("Liquid Retina XDR")) return "XDR (3024×1964)";
  if (display.includes("Liquid Retina") || display.includes("Retina")) {
    if (display.includes('15.3"')) return "Retina (2880×1864)";
    if (display.includes('13.6"')) return "Retina (2560×1664)";
    if (display.includes('16.2"')) return "XDR (3456×2234)";
    if (display.includes('14.2"')) return "XDR (3024×1964)";
    return "Retina";
  }
  if (display.includes("PixelSense")) return "PixelSense (2304×1536)";
  for (const r of RESOLUTION_MAP) {
    if (r.match.test(display)) return r.label;
  }
  return undefined;
}

function derivePanelType(display: string): string | undefined {
  if (display.includes("Mini LED")) return "Mini LED";
  if (display.includes("OLED")) return "OLED";
  if (display.includes("Liquid Retina XDR")) return "Liquid Retina XDR (mini-LED)";
  if (display.includes("Liquid Retina")) return "Liquid Retina";
  if (display.includes("PixelSense")) return "PixelSense";
  if (display.includes("Retina")) return "Retina";
  if (display.includes("IPS")) return "IPS";
  return undefined;
}

function deriveAspectRatio(display: string): string | undefined {
  const res = deriveResolution(display) ?? "";
  if (res.includes("×")) {
    const [w, h] = res.match(/(\d+)×(\d+)/)?.slice(1).map(Number) ?? [0, 0];
    if (w && h) return Math.round((w / h) * 10) / 10 === 1.78 ? "16:9" : "16:10";
  }
  if (display.includes("WQXGA") || display.includes("WUXGA") || display.includes("FHD+") || display.includes("2.8K") || display.includes("3.2K") || display.includes("3K")) return "16:10";
  return undefined;
}

function countPort(ports: string[], re: RegExp): number {
  return ports.reduce((sum, p) => {
    const m = p.match(re);
    if (!m) return sum;
    const n = m[1] ? parseInt(m[1], 10) : 1;
    return sum + (isNaN(n) ? 1 : n);
  }, 0);
}

/** Fill structured fields from existing display/port strings where not already provided. */
export function enrichSpecs(specs: ComputerSpecs): ComputerSpecs {
  const next = { ...specs };
  if (!next.resolution) next.resolution = deriveResolution(next.display);
  if (!next.panelType) next.panelType = derivePanelType(next.display);
  if (!next.aspectRatio) next.aspectRatio = deriveAspectRatio(next.display);
  if (next.touchscreen === undefined) next.touchscreen = /touch/i.test(next.display);

  if (next.usbA === undefined) {
    const n = countPort(next.ports, /USB-A(?: x(\d+))?/i);
    if (n > 0) next.usbA = n > 1 ? `USB-A ×${n}` : "USB-A ×1";
  }
  if (next.usbC === undefined) {
    const n = countPort(next.ports, /USB-C(?: x(\d+))?/i) + countPort(next.ports, /USB4(?: x(\d+))?/i);
    if (n > 0) next.usbC = n > 1 ? `USB-C ×${n}` : "USB-C ×1";
  }
  if (next.thunderbolt === undefined) {
    const n = countPort(next.ports, /Thunderbolt(?: ?\d)?(?: x(\d+))?/i);
    if (n > 0) next.thunderbolt = n > 1 ? `Thunderbolt ×${n}` : "Thunderbolt";
  }
  if (next.hdmi === undefined) {
    const n = countPort(next.ports, /HDMI(?: ?\d\.?\d?)?(?: x(\d+))?/i);
    if (n > 0) next.hdmi = `HDMI ×${n}`;
  }
  if (next.displayPort === undefined) {
    const n = countPort(next.ports, /DisplayPort(?: x(\d+))?/i);
    if (n > 0) next.displayPort = `DisplayPort ×${n}`;
  }
  if (next.sdCard === undefined) {
    next.sdCard = next.ports.some((p) => /sd card|microsd/i.test(p));
  }
  if (next.ethernet === undefined) {
    next.ethernet = next.ports.some((p) => /ethernet|2\.5g|10g/i.test(p));
  }
  if (next.audioJack === undefined) {
    next.audioJack = next.ports.some((p) => /3\.5mm/i.test(p));
  }
  return next;
}

