/** Apply chassis-level base specs for a model, then derive structured fields. */
function enrichVariant(modelId: string, variant: ComputerVariant): ComputerVariant {
  const base = MODEL_BASE_SPECS[modelId] ?? {};
  const merged: ComputerSpecs = { ...base, ...variant.specs };
  return { ...variant, specs: enrichSpecs(merged) };
}

