// === HELPER FUNCTIONS ===

/** Flatten all variants into a single array for backward compatibility */
export function getAllVariants(): ComputerVariant[] {
  return computerModels.flatMap((m) => m.variants.map((v) => enrichVariant(m.id, v)));
}

/** Find a variant by its ID across all models */
export function findVariantById(id: string): ComputerVariant | undefined {
  return getAllVariants().find((v) => v.id === id);
}

/** Find a model by variant ID */
export function findModelByVariantId(variantId: string): ComputerModel | undefined {
  return computerModels.find((m) => m.variants.some((v) => v.id === variantId));
}

/** Find a model by its own ID */
export function findModelById(modelId: string): ComputerModel | undefined {
  return computerModels.find((m) => m.id === modelId);
}

/** Get all variants of a model with enriched specs */
export function getModelVariants(modelId: string): ComputerVariant[] {
  const model = findModelById(modelId);
  if (!model) return [];
  return model.variants.map((v) => enrichVariant(model.id, v));
}

// Backward-compatible flat export (deprecated, use computerModels instead)
export const computers: ComputerVariant[] = getAllVariants();
